// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address newOwner) public {
        // The freshly deployed contract's owner is address(0), so the only
        // admissible caller is address(0) itself (the current owner).
        vm.prank(address(0));
        c.transferOwnership(newOwner);
        // General rule: after a successful transferOwnership(newOwner),
        // the public owner getter must equal newOwner for EVERY input.
        assertTrue(c.owner() == newOwner, "owner must equal newOwner after transferOwnership");
    }
}
